package com.kiwiplan.mes;

import java.util.List;
import java.util.stream.Collectors;

public class BatchPlanner {
    // Returns SKUs above a threshold; the caller later MUTATES the list.
    public List<String> highPriority(List<WorkItem> items) {
        List<String> result = items.stream()
            .filter(i -> i.getQty() > 10)
            .map(WorkItem::getSku)
            .collect(Collectors.toList()); // mutable ArrayList in Java 11
        result.add("EXPEDITE");            // caller mutates the result
        return result;
    }
}
